begin;
create extension if not exists pgtap with schema extensions;
select plan(24);
insert into public.barbershops(id,name,slug) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','A','rpc-a'),('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','B','rpc-b');
insert into auth.users(id,email) values('aaaaaaaa-0000-0000-0000-000000000001','a@test.local'),('bbbbbbbb-0000-0000-0000-000000000001','b@test.local');
insert into public.subscriptions(user_id,status) values('aaaaaaaa-0000-0000-0000-000000000001','active'),('bbbbbbbb-0000-0000-0000-000000000001','active');
update public.profiles set barbershop_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',role='owner' where id='aaaaaaaa-0000-0000-0000-000000000001';
update public.profiles set barbershop_id='bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',role='owner' where id='bbbbbbbb-0000-0000-0000-000000000001';
insert into public.barbers(id,barbershop_id,name) values('10000000-0000-0000-0000-000000000001','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Ana 30'),('10000000-0000-0000-0000-000000000002','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Bia 45'),('20000000-0000-0000-0000-000000000001','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','Caio');
insert into public.services(id,barbershop_id,name,price,duration_minutes) values('30000000-0000-0000-0000-000000000001','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Corte',35,30),('40000000-0000-0000-0000-000000000001','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','Outro',80,60);
insert into public.barber_services(id,barbershop_id,barber_id,service_id,price,duration_minutes) values('50000000-0000-0000-0000-000000000001','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001',40,30),('50000000-0000-0000-0000-000000000002','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000001',50,45),('60000000-0000-0000-0000-000000000001','bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',80,60);
insert into public.barbershop_settings(barbershop_id,slot_interval_minutes) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',15);
insert into public.barber_work_hours(barbershop_id,barber_id,day_of_week,start_time,end_time,lunch_start_time,lunch_end_time) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000001',extract(dow from date '2030-07-22'),'09:00','18:00','12:00','13:00'),('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000002',extract(dow from date '2030-07-22'),'09:00','13:00','11:30','12:00'),('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000001',extract(dow from date '2030-07-23'),'09:00','18:00','12:00','13:00');
insert into public.barber_blocked_times(barbershop_id,barber_id,start_at,end_at) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000002','2030-07-22 10:00+00','2030-07-22 10:30+00');
insert into public.add_ons(id,barbershop_id,name,price) values('70000000-0000-0000-0000-000000000001','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Extra',5);
insert into public.products(id,barbershop_id,name,sale_price,stock_quantity) values('80000000-0000-0000-0000-000000000001','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Pomade',12,10);

select results_eq($$select price,duration_minutes from public.barber_services where service_id='30000000-0000-0000-0000-000000000001' order by barber_id$$,$$select * from (values(40.00::numeric,30),(50.00::numeric,45)) v(price,duration_minutes)$$,'per-barber config');
set local role anon;
select is((select count(*) from public.barber_services where barbershop_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),2::bigint,'anon reads available');
reset role;
set local role authenticated;
set local "request.jwt.claim.sub" = 'aaaaaaaa-0000-0000-0000-000000000001';
select throws_ok($$insert into public.barber_services(barbershop_id,barber_id,service_id,price,duration_minutes) values('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','20000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001',1,30)$$,'42501',null,'tenant write denied');
reset role;
select throws_ok($$select public.create_public_appointment_with_barber_service_and_products('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','X','1199',null,'60000000-0000-0000-0000-000000000001',1,'2030-07-22 09:00+00',null,null,'[]')$$,'P0001','INVALID_BARBER_SERVICE','cross tenant denied');
select ok('09:30'::time not in(select available_time from public.get_public_available_slots_for_service('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','50000000-0000-0000-0000-000000000002','2030-07-22')),'duration respects block');
select ok('10:30'::time in(select available_time from public.get_public_available_slots_for_service('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','50000000-0000-0000-0000-000000000002','2030-07-22')),'grid independent of duration');
select ok('11:00'::time not in(select available_time from public.get_public_available_slots_for_service('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','50000000-0000-0000-0000-000000000002','2030-07-22')),'duration respects lunch');
select throws_ok($$select public.create_public_appointment_with_barber_service_and_products('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','X','1188',null,'50000000-0000-0000-0000-000000000002',0,'2030-07-22 12:00+00',null,null,'[]')$$,'P0001','CONFIG_CHANGED','stale denied');

create temporary table receipt as select public.create_public_appointment_with_barber_service_and_products('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Client','(11) 97777-6666','c@test.local','50000000-0000-0000-0000-000000000002',1,'2030-07-22 09:00+00',null,array['70000000-0000-0000-0000-000000000001'::uuid],'[{"productId":"80000000-0000-0000-0000-000000000001","quantity":2}]') value;
select results_eq($$select value->>'barberName',value->>'serviceName',value->>'servicePrice',value->>'serviceDurationMinutes' from receipt$$,$$values('Bia 45','Corte','50.00','45')$$,'receipt identity');
select is((select concat_ws('|',value->>'addOnTotal',value->>'productSubtotal',value->>'attendanceTotal',value->>'totalAtShop') from receipt),'5.00|24.00|55.00|79.00','receipt totals');
select is((select concat_ws('|',value->>'startAt',value->>'endAt') from receipt),'2030-07-22T09:00:00+00:00|2030-07-22T09:45:00+00:00','receipt interval');
select is((select concat_ws('|',service_price::text,service_duration_minutes::text,total_price::text) from public.appointments where id=(select(value->>'appointmentId')::uuid from receipt)),'50.00|45|55.00','appointment snapshots');
select is((select price::text from public.appointment_add_ons where appointment_id=(select(value->>'appointmentId')::uuid from receipt)),'5.00','addon snapshot');
select is((select concat_ws('|',quantity::text,unit_price::text) from public.appointment_products where appointment_id=(select(value->>'appointmentId')::uuid from receipt)),'2|12.00','product snapshot');
select throws_ok($$select public.create_public_appointment_with_barber_service_and_products('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Overlap','1177',null,'50000000-0000-0000-0000-000000000002',1,'2030-07-22 09:15+00',null,null,'[]')$$,'P0001','SLOT_UNAVAILABLE','overlap denied');
update public.appointments set status='pending' where id=(select(value->>'appointmentId')::uuid from receipt);
insert into public.barber_blocked_times(barbershop_id,barber_id,start_at,end_at) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','10000000-0000-0000-0000-000000000002','2030-07-22 09:00+00','2030-07-22 09:45+00');
select throws_ok($$update public.appointments set status='confirmed' where id=(select(value->>'appointmentId')::uuid from receipt)$$,'P0001','SLOT_UNAVAILABLE','pending to confirmed revalidates interval under lock');
delete from public.barber_blocked_times where barber_id='10000000-0000-0000-0000-000000000002' and start_at='2030-07-22 09:00+00';
set local role authenticated;
set local "request.jwt.claim.sub" = 'aaaaaaaa-0000-0000-0000-000000000001';
select throws_ok($$select public.save_service_with_barbers(null,'No assignment',null,true,'[]')$$,'P0001','SERVICE_REQUIRES_AVAILABLE_BARBER','create needs barber');
reset role;
set local role authenticated;
set local "request.jwt.claim.sub" = 'aaaaaaaa-0000-0000-0000-000000000001';
select lives_ok($$select public.save_service_with_barbers('30000000-0000-0000-0000-000000000001','Corte',null,true,'[{"barberId":"10000000-0000-0000-0000-000000000001","price":40,"durationMinutes":30,"isAvailable":false},{"barberId":"10000000-0000-0000-0000-000000000002","price":50,"durationMinutes":45,"isAvailable":false}]')$$,'edit allows zero');
reset role;
select is((select configuration_version from public.barber_services where id='50000000-0000-0000-0000-000000000001'),2::bigint,'version increments');
update public.barber_services set is_available=true where id='50000000-0000-0000-0000-000000000001';
select lives_ok($$select public.create_public_appointment_with_client('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Legacy','1166',null,'10000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','2030-07-23 09:00+00',null,null)$$,'legacy callable');
select is((select concat_ws('|',service_price::text,service_duration_minutes::text) from public.appointments where client_id=(select id from public.clients where normalized_phone='1166')),'40.00|30','legacy snapshots');
select is((select count(*) from private.legacy_booking_rpc_calls where function_name='create_public_appointment_with_client'),1::bigint,'legacy telemetry');
select ok(not has_function_privilege('anon','private.create_appointment_from_barber_service(uuid,text,text,text,uuid,bigint,timestamptz,text,uuid[])','EXECUTE'),'core private');
select ok(not has_function_privilege('authenticated','private.assert_bookable_appointment_interval(uuid,uuid,uuid,uuid,timestamptz,timestamptz,text,uuid)','EXECUTE'),'guard private');
select * from finish();
rollback;
